126	        private void generaPdf(ObjectMapper mapper, ObjectNode data, String outputFileName) throws Exception {
127	            JasperReport mainReport = compile(MAIN_REPORT);
128	            JasperReport subreportAllegati = compile(SUBREPORT_ALLEGATI);
129	            JasperReport subreportSoggetti = compile(SUBREPORT_SOGGETTI);
130	
131	            Map<String, Object> parameters = new HashMap<>();
132	            parameters.put(PARAM_SUBREPORT_ALLEGATI, subreportAllegati);
133	            parameters.put(PARAM_SUBREPORT_SOGGETTI, subreportSoggetti);
134	            parameters.put(PARAM_LISTA_ALLEGATI, buildListaAllegati());
135	            parameters.put(PARAM_NOME_COGNOME_UTENTE, "Alfredo Serafini");
136	
137	            byte[] jsonBytes = mapper.writeValueAsBytes(data);
138	            JsonDataSource dataSource = new JsonDataSource(new ByteArrayInputStream(jsonBytes));
139	
140	            JasperPrint jasperPrint = JasperFillManager.fillReport(mainReport, parameters, dataSource);
141	
142	            Path outputPath = writePdf(jasperPrint, outputFileName);
143	
144	            assertTrue("Il PDF generato non esiste: " + outputPath, Files.exists(outputPath));
145	            assertTrue("Il PDF generato è vuoto: " + outputPath, Files.size(outputPath) > 0);
146	        }
