148	        private JasperReport compile(String resourcePath) throws Exception {
149	            try (InputStream stream = getClass().getResourceAsStream(resourcePath)) {
150	                if (stream == null) {
151	                    throw new IllegalStateException("Risorsa jrxml non trovata nel classpath: " + resourcePath);
152	                }
153	                return JasperCompileManager.compileReport(stream);
154	            }
155	        }
156	
157	        private Path writePdf(JasperPrint jasperPrint, String outputFileName) throws Exception {
158	            Path outputDir = Paths.get(OUTPUT_DIR);
159	            Files.createDirectories(outputDir);
160	            Path outputPath = outputDir.resolve(outputFileName);
161	
162	            try (OutputStream outputStream = Files.newOutputStream(outputPath)) {
163	                JRPdfExporter exporter = new JRPdfExporter();
164	                exporter.setExporterInput(new SimpleExporterInput(jasperPrint));
165	                exporter.setExporterOutput(new SimpleOutputStreamExporterOutput(outputStream));
166	                exporter.exportReport();
167	            }
168	            return outputPath;
169	        }
