144	    private JasperReport compile(String resourcePath) throws Exception {
145	        try (InputStream stream = getClass().getResourceAsStream(resourcePath)) {
146	            if (stream == null) {
147	                throw new IllegalStateException("Risorsa jrxml non trovata nel classpath: " + resourcePath);
148	            }
149	            return JasperCompileManager.compileReport(stream);
150	        }
