160	            exporter.setExporterInput(new SimpleExporterInput(jasperPrint));
161	            exporter.setExporterOutput(new SimpleOutputStreamExporterOutput(outputStream));
162	            exporter.exportReport();
163	        }
164	        return outputPath;
165	    }
