        data.put("codiceFiscaleEnte", "93000000727");
        data.put("pIvaEnte", "12345678901");
        data.put("nomeCognomeLegaleRappresentante", "Mario Rossi");

        // Progetti / programmazione
        data.put("titoloProgetto2026", "Puglia in Scena 2026");
        data.put("titoloProgetto2025", "Puglia in Scena 2025");
        data.put("titoloProgrammazioneTriennale", "Puglia Cultura 2025/2027");

        // Istanza principale
        data.put("idIstanzaPrincipale", "100245");
        data.put("numeroProtocolloIstanzaPrincipale", "0098765");
        data.put("dataProtocolloIstanzaPrincipale", "18/07/2025");

        // Verbale esiti procedura
        data.put("dataVerbaleEsitiProcedura", "10/09/2025");
        data.put("numeroProtocolloVerbaleEsitiProcedura", "0123456");
        data.put("dataProtocolloVerbaleEsitiProcedura", "12/09/2025");

        // Determina approvazione 2025
        data.put("codiceCifraDeterminaApprovazione2025", "ABC/2025/00123");
        data.put("dataDeterminaApprovazione2025", "30/09/2025");
        data.put("importoAssegnato2025", "150.000,00");
        data.put("numeroCapitoloRegionale2025", "U0901010");
        data.put("dataSottoscrizioneDisciplinare2025", "15/10/2025");

        // Provvedimento approvazione 2026
        data.put("codiceCifraProvvedimentoApprovazione2026", "ABC/2026/00045");
        data.put("dataProvvedimentoApprovazione2026", "20/02/2026");
        data.put("dataInvioDomandaProgetto2026", "15/01/2026");
        data.put("numeroProtocolloDomandaProgetto2026", "0011223");
        data.put("importoAssegnato2026", "180.000,00");
        data.put("numeroCapitoloSpesa2026", "U0901011");
        data.put("denominazioneCapitoloSpesa2026", "Spese per attività culturali e di spettacolo dal vivo");

        // Atto dirigenziale ammissione 2026
        data.put("numeroAttoDirigenzialeAmmissione2026", "215");
        data.put("dataAttoDirigenzialeAmmissione2026", "01/03/2026");

        // Cronoprogramma 2026
        data.put("dataInizioAttivita2026", "01/04/2026");
        data.put("dataFineAttivita2026", "31/12/2026");

        return data;
    }
}

